INSERT INTO reviews (id,product_id,source,rating,title,body,created_at) VALUES
('sample-review-bottle-1','sample-product-bottle','csv',5,'Stays cold all day','Filled it with ice at 7am and it was still cold after a full day of hiking.',datetime('now','-20 days')),
('sample-review-bottle-2','sample-product-bottle','csv',5,'No leaks in my bag','The cap is solid. No leaks even when it rolled around in my backpack.',datetime('now','-19 days')),
('sample-review-bottle-3','sample-product-bottle','csv',4,'Great but heavy','Keeps water cold for hours, but it is heavier than my old plastic bottle.',datetime('now','-18 days')),
('sample-review-bottle-4','sample-product-bottle','csv',5,'Fits my car','Fits my car cup holder, which most insulated bottles do not.',datetime('now','-17 days')),
('sample-review-bottle-5','sample-product-bottle','csv',3,'Paint chipped','The paint chipped after two weeks of dropping it on rocks.',datetime('now','-16 days')),
('sample-review-bottle-6','sample-product-bottle','csv',5,'Easy to carry','The carry loop is sturdy and clips onto my pack easily.',datetime('now','-15 days')),
('sample-review-lamp-1','sample-product-lamp','paste',5,'Bright enough for the tent','Bright enough to light the whole tent on the medium setting.',datetime('now','-12 days')),
('sample-review-lamp-2','sample-product-lamp','paste',4,'Battery is decent','Lasted two nights on low before I had to charge it.',datetime('now','-11 days')),
('sample-review-lamp-3','sample-product-lamp','paste',4,'Handy hook','The hook folds flat so it packs small.',datetime('now','-10 days'));
INSERT INTO launches (id,product_id,kind,status,insights,listing_copy,steps,config,created_at,updated_at) VALUES
('sample-launch-bottle','sample-product-bottle','launch','ready','{"source": "reviews", "review_insights": [{"insight": "Buyers notice the bottle keeps drinks cold through a full day", "sentiment": "positive", "journey": "post_purchase", "quotes": ["still cold after a full day of hiking", "Keeps water cold for hours"], "reliability": 88, "review_count": 2}, {"insight": "A leak-proof cap matters when the bottle rides in a bag", "sentiment": "positive", "journey": "pre_purchase", "quotes": ["No leaks even when it rolled around in my backpack"], "reliability": 76, "review_count": 1}, {"insight": "Some buyers find it heavier than plastic bottles", "sentiment": "negative", "journey": "post_purchase", "quotes": ["it is heavier than my old plastic bottle"], "reliability": 58, "review_count": 1}, {"insight": "The coating can chip after rough use", "sentiment": "negative", "journey": "post_purchase", "quotes": ["The paint chipped after two weeks"], "reliability": 44, "review_count": 1}], "product_features": [{"feature": "Keeps drinks cold for a full day", "journey": "post_purchase", "source": "reviews"}, {"feature": "Leak-proof screw cap with carry loop", "journey": "pre_purchase", "source": "listing"}, {"feature": "Fits standard car cup holders", "journey": "pre_purchase", "source": "reviews"}, {"feature": "750 ml, 18/8 stainless steel", "journey": "pre_purchase", "source": "specs"}], "conversion_drivers": [{"driver": "All-day cold retention", "kind": "driver", "relevance": 1, "journey": "pre_purchase"}, {"driver": "Leak-proof cap for bags", "kind": "driver", "relevance": 2, "journey": "pre_purchase"}, {"driver": "Weight compared with plastic", "kind": "blocker", "relevance": 3, "journey": "pre_purchase"}, {"driver": "Coating durability on rough use", "kind": "blocker", "relevance": 4, "journey": "post_purchase"}]}','{"title": "Northlight Trail Bottle 750 ml, Double-Wall Stainless Steel Water Bottle with Leak-Proof Cap and Carry Loop, Fits Car Cup Holders", "bullets": ["COLD ALL DAY: Double-wall stainless steel keeps water cold from morning to evening on the trail.", "LEAK-PROOF CAP: The screw cap seals tight, so the bottle can ride loose in a backpack.", "EASY TO CARRY: A sturdy carry loop clips onto packs, bags and bike frames.", "FITS YOUR CUP HOLDER: The 750 ml body fits standard car cup holders.", "BUILT FOR THE OUTDOORS: 18/8 stainless steel with a textured grip finish."], "description": "The Northlight Trail Bottle keeps water cold through a full day outside. Its double-wall 18/8 stainless steel body holds 750 ml, the screw cap seals tight for travel in a bag, and the carry loop clips onto a pack. The slim base fits standard car cup holders, so it moves from the trail to the drive home.", "backend_keywords": "insulated water bottle hiking bottle stainless steel flask leak proof bottle cup holder bottle camping"}','[{"step": "reading_product_data", "label": "Reading product data", "status": "done", "meta": ["4 features", "0 images"]}, {"step": "analyzing_customer_voice", "label": "Analyzing customer voice", "status": "done", "meta": ["6 reviews", "4.5 rating"]}, {"step": "ranking_drivers", "label": "Ranking conversion drivers/blockers", "status": "done", "meta": ["2 drivers", "2 blockers"]}, {"step": "content_briefs", "label": "Content strategy & listing copy", "status": "done", "meta": ["title + 5 bullets", "backend keywords"]}, {"step": "generating_assets", "label": "Generating assets", "status": "pending", "meta": []}]','{"image_type": "listing", "qty": 1, "format": "1:1"}',datetime('now','-5 days'),datetime('now','-5 days'));
